changeSet.sql:
DO $$
DECLARE
    channel RECORD;
    new_notification_id BIGINT;
    target_workspace_id BIGINT;
    notification_type INT;
    settings TEXT;
    config JSONB;
    email_value TEXT;
BEGIN
    FOR channel IN SELECT * FROM ai_observability_notification_channel LOOP
        config := channel.config::jsonb;

        IF channel.type = 0 THEN
            notification_type := 1;
            settings := jsonb_strip_nulls(
                jsonb_build_object('webhook', config->>'url', 'webhookSecret', config->>'secret'))::text;
        ELSIF channel.type = 1 THEN
            notification_type := 0;

            IF jsonb_typeof(config->'recipients') = 'array' THEN
                email_value := config->'recipients'->>0;
            ELSE
                email_value := split_part(coalesce(config->>'recipients', config->>'to', ''), ',', 1);
            END IF;

            settings := jsonb_build_object('email', trim(coalesce(email_value, '')))::text;
        ELSE
            notification_type := 2;
            settings := jsonb_build_object('slackWebhookUrl', config->>'webhookUrl')::text;
        END IF;

        INSERT INTO notification (
            name, type, settings, created_by, created_date, last_modified_by, last_modified_date, version)
        VALUES (channel.name, notification_type, settings, 'system', now(), 'system', now(), 1)
        RETURNING id INTO new_notification_id;

        SELECT workspace_id INTO target_workspace_id
        FROM workspace_ai_observability_notification_channel
        WHERE ai_observability_notification_channel_id = channel.id
        LIMIT 1;

        IF target_workspace_id IS NOT NULL THEN
            INSERT INTO workspace_notification (workspace_id, notification_id, created_date, version)
            VALUES (target_workspace_id, new_notification_id, now(), 0);
        END IF;

        UPDATE ai_observability_alert_rule_channel
        SET notification_channel_id = new_notification_id
        WHERE notification_channel_id = channel.id;
    END LOOP;
END $$;
